#!/bin/bash
# ============================================================================
# Downloads the results of every node of ips.txt.
#
# USAGE: bash V3_Collect.sh [target folder]
# On each node the result folders, the stored suites and the logs are packed
# into one archive; the raw GUITAR test files and the product model files are
# left out (they are regenerated by the pipeline). The archive of node i is
# unpacked into <target>/node<i>/. A node that has not finished is reported.
# ============================================================================
set -u
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
IPS_FILE="$SCRIPT_DIR/ips.txt"
TARGET=${1:-"$SCRIPT_DIR/../../../results/v3-$(date +%Y%m%d_%H%M%S)"}
mkdir -p "$TARGET"
REMOTE=/root/esg-with-feature-expressions

index=0
while IFS= read -r line || [ -n "$line" ]; do
    ip=$(echo "$line" | awk '{print $1}')
    case "$ip" in ''|'#'*) continue ;; esac
    node="node$(printf '%02d' "$index")"; index=$((index + 1))
    echo "== $node ($ip)"
    if ssh -o StrictHostKeyChecking=no "root@$ip" "test -f $REMOTE/files/logs/v3/ALL_DONE"; then
        echo "   finished"
    else
        echo "   NOT FINISHED: $(ssh "root@$ip" "tail -n 1 $REMOTE/files/logs/v3/jobs.csv 2>/dev/null")"
    fi
    ssh "root@$ip" "cd $REMOTE && tar czf /root/v3_$node.tgz \
        --exclude='*.tst' --exclude='*.EFG' --exclude='*.DOT' --exclude='*.dot' --exclude='files/archive_before_*' \
        files/logs files/Cases/*/testsequences files/Cases/*/comparativeEfficiencyTestPipeline \
        files/Cases/*/extremeScalabilityTestPipeline files/Cases/*/faultdetection files/Cases/*/EFGs/efg_results \
        files/Cases/*/EFGs/efg_testsequences/stored files/Cases/*/*_ProductConfigurations.txt 2>/dev/null; ls -l /root/v3_$node.tgz"
    mkdir -p "$TARGET/$node"
    scp -o StrictHostKeyChecking=no "root@$ip:/root/v3_$node.tgz" "$TARGET/$node/" \
        && tar xzf "$TARGET/$node/v3_$node.tgz" -C "$TARGET/$node" \
        && echo "   unpacked into $TARGET/$node"
done < "$IPS_FILE"
echo "Results in $TARGET"
